-- Forward-only derived retrieval state. Existing content, Jobs and outbox stay owned.
CREATE TABLE retrieval_scopes(workspace_id TEXT NOT NULL REFERENCES workspace(id),scope_sha256 TEXT NOT NULL,roots_json TEXT NOT NULL CHECK(json_valid(roots_json)),created_at TEXT NOT NULL,index_version TEXT,PRIMARY KEY(workspace_id,scope_sha256));
CREATE TABLE retrieval_generations(index_version TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,scope_sha256 TEXT NOT NULL,corpus_sha256 TEXT NOT NULL,manifest_json TEXT NOT NULL CHECK(json_valid(manifest_json)),manifest_sha256 TEXT NOT NULL,job_id TEXT NOT NULL UNIQUE REFERENCES jobs(id),built_at TEXT NOT NULL,FOREIGN KEY(workspace_id,scope_sha256) REFERENCES retrieval_scopes(workspace_id,scope_sha256));
CREATE TABLE retrieval_chunks(chunk_id TEXT PRIMARY KEY,index_version TEXT NOT NULL REFERENCES retrieval_generations(index_version),ref_json TEXT NOT NULL CHECK(json_valid(ref_json)),tokens TEXT NOT NULL,terms_sha256 TEXT NOT NULL,UNIQUE(index_version,ref_json));
CREATE VIRTUAL TABLE retrieval_fts USING fts5(workspace_id UNINDEXED,scope_sha256 UNINDEXED,index_version UNINDEXED,chunk_id UNINDEXED,tokens,tokenize='ascii');
CREATE TABLE retrieval_jobs(job_id TEXT PRIMARY KEY REFERENCES jobs(id),workspace_id TEXT NOT NULL,scope_sha256 TEXT NOT NULL,sequence INTEGER NOT NULL CHECK(sequence>0),input_json TEXT NOT NULL CHECK(json_valid(input_json)),input_sha256 TEXT NOT NULL,result_json TEXT CHECK(result_json IS NULL OR json_valid(result_json)),result_sha256 TEXT,UNIQUE(workspace_id,scope_sha256,sequence),FOREIGN KEY(workspace_id,scope_sha256) REFERENCES retrieval_scopes(workspace_id,scope_sha256),CHECK((result_json IS NULL)=(result_sha256 IS NULL)));
CREATE TABLE retrieval_commands(workspace_id TEXT NOT NULL REFERENCES workspace(id),route TEXT NOT NULL,key TEXT NOT NULL,request_json TEXT NOT NULL CHECK(json_valid(request_json)),request_sha256 TEXT NOT NULL,ack_json TEXT NOT NULL CHECK(json_valid(ack_json)),ack_sha256 TEXT NOT NULL,job_id TEXT NOT NULL REFERENCES jobs(id),created_at TEXT NOT NULL,scope_sha256 TEXT NOT NULL,PRIMARY KEY(workspace_id,route,key),FOREIGN KEY(workspace_id,scope_sha256) REFERENCES retrieval_scopes(workspace_id,scope_sha256));
CREATE TABLE retrieval_input_events(sequence INTEGER PRIMARY KEY AUTOINCREMENT,workspace_id TEXT NOT NULL REFERENCES workspace(id),source TEXT NOT NULL,occurred_at TEXT NOT NULL);
CREATE TABLE retrieval_consumption(workspace_id TEXT PRIMARY KEY REFERENCES workspace(id),last_sequence INTEGER NOT NULL CHECK(last_sequence>=0));
CREATE TRIGGER retrieval_generations_no_update BEFORE UPDATE ON retrieval_generations BEGIN SELECT RAISE(ABORT,'immutable retrieval generation'); END;
CREATE TRIGGER retrieval_generations_no_delete BEFORE DELETE ON retrieval_generations BEGIN SELECT RAISE(ABORT,'immutable retrieval generation'); END;
CREATE TRIGGER retrieval_chunks_no_update BEFORE UPDATE ON retrieval_chunks BEGIN SELECT RAISE(ABORT,'immutable retrieval chunk'); END;
CREATE TRIGGER retrieval_chunks_no_delete BEFORE DELETE ON retrieval_chunks BEGIN SELECT RAISE(ABORT,'immutable retrieval chunk'); END;
CREATE TRIGGER retrieval_commands_no_update BEFORE UPDATE ON retrieval_commands BEGIN SELECT RAISE(ABORT,'immutable retrieval command'); END;
CREATE TRIGGER retrieval_commands_no_delete BEFORE DELETE ON retrieval_commands BEGIN SELECT RAISE(ABORT,'immutable retrieval command'); END;
CREATE TRIGGER retrieval_jobs_input_immutable BEFORE UPDATE OF job_id,workspace_id,scope_sha256,sequence,input_json,input_sha256 ON retrieval_jobs BEGIN SELECT RAISE(ABORT,'immutable retrieval input'); END;
CREATE TRIGGER retrieval_jobs_result_immutable BEFORE UPDATE OF result_json,result_sha256 ON retrieval_jobs WHEN OLD.result_json IS NOT NULL BEGIN SELECT RAISE(ABORT,'immutable retrieval result'); END;
CREATE TRIGGER retrieval_jobs_no_delete BEFORE DELETE ON retrieval_jobs BEGIN SELECT RAISE(ABORT,'immutable retrieval job allocation'); END;
CREATE TRIGGER retrieval_input_events_no_update BEFORE UPDATE ON retrieval_input_events BEGIN SELECT RAISE(ABORT,'immutable retrieval invalidation'); END;
CREATE TRIGGER retrieval_input_events_no_delete BEFORE DELETE ON retrieval_input_events BEGIN SELECT RAISE(ABORT,'immutable retrieval invalidation'); END;
